SYSTEM = '\n'.join(text for _, text in _SECTIONS) + '\n'

def system_prompt(phase):
    if phase not in ('modeling', 'analysis'):
        raise ValueError('unknown workflow phase')
    return '\n'.join(text for scope, text in _SECTIONS if scope in ('common', phase)) + '\n' + _ANALYSIS_ENTRY_GUARD + _CONTENT_REFERENCES


_CONTENT_REFERENCES = (
    'A content_ref reuses exact content already present in THIS request: select its section, optional source_id/turn_id/symbol, '
    'then follow path keys; slice=[start,length] selects text, or slices plus join reconstruct an exact head/tail excerpt. Resolve locally without another tool call. '
    'The surrounding source, version, role, state and confirmation still apply; shared text does not merge decisions or prove verification.\n')


# A first analysis request can arrive while the retained workflow is modeling.
# Keep the transition constraints even before analysis_context selects the phase.
_ANALYSIS_ENTRY_GUARD = (
    'For a static-analysis request, read analysis_context before configure_study or solve, unless current analysis_setup already supplies it. '
    'Material, loading and mounting require user facts or explicitly authorized assumptions; ask once for missing critical physical inputs. '
    'A modeling-only request does not authorize a solve. Low residual does not establish mesh accuracy. Unknown checks remain unknown.\n')


_ITERATION_HEAD = '\nPrioritize quick, correct iterations. Default low reasoning is intentional; do not spend long reasoning on documentation calls. For a complex assembly, include a short ordered components list with depends_on in set_modeling_requirements; this is the same call, not a separate planning round. '
_MODULE_ITERATION = 'For modular assemblies prefer compatible code modules: search interfaces, register only genuinely missing Python modules, then build by module_assembly references instead of emitting a whole program. Each module returns one local-coordinate Brep. Instance depends_on declares geometry inputs, supplied as copies. Parameter/translation bindings can refer to earlier component parameters. For existing assemblies prefer preview_build with base_assembly_artifact and assembly_edits=[{component_id,parameters:{changed_name:value}}]; backend preserves other instances and bindings. Read one component with read_code_assembly when needed. Geometry reuse and placement changes are tracked separately. Module build receipts report module_rebuild and module_mesh_reused; use these actual counters when describing incremental reuse. Code module registration validates syntax, not feature correctness; inspect real build checks before claiming success. '
_ITERATION_TAIL = 'Build and validate a small coherent component or group, keep named result bodies, and reuse unchanged parts from parts with use_current=true. Assemble using transforms in dependency order; do not boolean-union separate mechanical parts unless the user requests one fused solid. For a parameter-only change use preview_build(parameters={existing_name:new_value}) without script/use_current/replay_of; the backend replays saved inputs. Successful CAD receipts include modeling_check; use that evidence directly instead of spending another call on check_modeling at the same revision. task_focus.geometry_summary gives body dimensions, areas, volumes, bbox-inferred face levels and bbox relations. After a successful build prefer a concise finish using these measured facts, with manual checks explicitly unverified. Use at most two targeted extra inspections at an unchanged artifact unless an actual failed check requires repair. Do not page through every face merely because a manual checker says unknown. Bbox relations and total volume alone do not prove wall thickness or fit. Do not repeat unsupported manual checks or broad topology scans. Inspect only the changed feature. If working_script is truncated, expand the relevant saved input before editing; do not reconstruct missing code from guesses.'

def iteration_prompt(module_mode):
    return _ITERATION_HEAD + (_MODULE_ITERATION if module_mode else '') + _ITERATION_TAIL
